import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../../core/theme/app_theme.dart';
import '../../../../data/finance_providers.dart';
import '../../../../data/models/financial_models.dart';
class ReportsScreen extends ConsumerWidget { const ReportsScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final data=ref.watch(transactionsProvider); return Scaffold(backgroundColor:PennyPalColors.black, appBar:AppBar(backgroundColor:PennyPalColors.black,title:const Text('Reports',style:TextStyle(color:Colors.white))), body:data.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('$e')),data:(tx){final income=tx.where((t)=>t.type==TransactionType.income).fold<double>(0,(a,t)=>a+t.amount);final expense=tx.where((t)=>t.type==TransactionType.expense).fold<double>(0,(a,t)=>a+t.amount);return ListView(padding:const EdgeInsets.all(20),children:[_row('Total income',income,Colors.green),_row('Total expenses',expense,Colors.red),_row('Balance',income-expense,Colors.white)]); })); } Widget _row(String label,double value,Color color)=>Container(margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(16),color:PennyPalColors.surface,child:Row(children:[Text(label,style:const TextStyle(color:Colors.white)),const Spacer(),Text('₦${value.toStringAsFixed(0)}',style:TextStyle(color:color,fontWeight:FontWeight.w800))])); }
